-- 只读结构和refs-only一致性；不输出body、HMAC值、sessionRef或绑定参数。
SELECT table_name,engine FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN ('ai_memory_summary_watermark','ai_memory_summary_source','ai_memory_summary_plan','ai_memory_summary_segment') ORDER BY table_name;
SELECT table_name,column_name,column_type,is_nullable,column_default,collation_name FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name IN ('ai_memory_summary_watermark','ai_memory_summary_source','ai_memory_summary_plan','ai_memory_summary_segment') ORDER BY table_name,ordinal_position;
SELECT trigger_name,action_timing,event_manipulation,action_statement FROM information_schema.triggers WHERE trigger_schema=DATABASE() AND trigger_name LIKE 'trg_summary_%' ORDER BY trigger_name;
SELECT tc.table_name,tc.constraint_name,tc.constraint_type,cc.check_clause FROM information_schema.table_constraints tc LEFT JOIN information_schema.check_constraints cc ON cc.constraint_schema=tc.constraint_schema AND cc.constraint_name=tc.constraint_name WHERE tc.table_schema=DATABASE() AND tc.table_name IN ('ai_memory_summary_watermark','ai_memory_summary_source','ai_memory_summary_plan','ai_memory_summary_segment') ORDER BY tc.table_name,tc.constraint_name;
SELECT COUNT(*) AS invalid_summary_message_anchors FROM ai_memory_summary_source m LEFT JOIN ai_memory_source s ON s.tenant_id=m.tenant_id AND s.id=m.message_id WHERE s.id IS NULL OR s.source_type<>'MESSAGE' OR s.source_object_ref<>m.message_id OR s.source_version<>CAST(m.content_hash AS BINARY);
SELECT COUNT(*) AS invalid_summary_scrubbed_bodies FROM ai_memory_summary_segment WHERE state='SCRUBBED' AND (encrypted_payload IS NOT NULL OR nonce IS NOT NULL OR auth_tag IS NOT NULL OR content_hmac IS NOT NULL);
SELECT table_name,index_name,non_unique,seq_in_index,column_name,sub_part FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name IN ('ai_memory_summary_watermark','ai_memory_summary_source','ai_memory_summary_plan','ai_memory_summary_segment') ORDER BY table_name,index_name,seq_in_index;
SELECT table_name,constraint_name,column_name,referenced_table_name,referenced_column_name FROM information_schema.key_column_usage WHERE table_schema=DATABASE() AND referenced_table_name IS NOT NULL AND table_name IN ('ai_memory_summary_watermark','ai_memory_summary_source','ai_memory_summary_plan','ai_memory_summary_segment') ORDER BY table_name,constraint_name,ordinal_position;
